  start:"La plataforma como la dibujó su equipo: una lista de productos. Tres de las partes que lo cruzan todo no tienen nada real debajo.",
  alt:"Ocho cajas: cuatro partes a lo largo del camino y cuatro que lo cruzan todo, cada una con el producto que tiene debajo, o una caja punteada donde no hay nada; cada caja marcada cuando un día que la necesita sale bien o mal.",
  goals:[["bill","Decir por qué la cuenta subió a la mitad"],["laptop","Un portátil se revisa antes de leer una fila"],["order","El trabajo de medidores espera la carga de facturación"],["gap","Dibuja primero las partes, y el hueco se ve"]],
  onL:"Las partes que lo cruzan",daysL:"Tres días",viewL:"Dibujar primero",views:[["products","Los productos"],["parts","Las partes"]],
  fixes:[{k:"obs",t:"Cada trabajo con dueño y costo",on:"Observar: cada trabajo lleva su dueño, y los registros de la plataforma dicen cuánto cuesta cada uno.",off:"Nadie puede decir qué trabajo cuesta cuánto."},
   {k:"sec",t:"Revisado por el catálogo",on:"Asegurar: el catálogo revisa cada pedido antes de leer una fila.",off:"Estar en la red basta para leer los archivos."},
   {k:"orc",t:"Los trabajos esperan lo que necesitan",on:"Orquestar: cada trabajo empieza cuando llegó lo que necesita.",off:"Los trabajos empiezan a hora fija, llegue lo que llegue."}],
  parts:[{k:"in",t:"Traer",prod:"Conectores"},{k:"store",t:"Guardar una vez",prod:"Tablas abiertas"},{k:"proc",t:"Procesar",prod:"Modelos dbt"},{k:"serve",t:"Servir",prod:"Tableros, API"},
   {k:"gov",t:"Catalogar, gobernar",prod:"El catálogo"},{k:"sec",t:"Asegurar",prod:"Revisión del catálogo",fix:"sec",none:""},{k:"orc",t:"Orquestar",prod:"A pedido",fix:"orc",none:"A las dos"},{k:"obs",t:"Observar",prod:"Costo por dueño",fix:"obs",none:""}],
  events:[{b:"Septiembre: la cuenta subió a la mitad",part:"obs",goal:"bill",ok:"Los registros de la plataforma muestran qué trabajos crecieron, y de quién son: tres de comercialización corrían cada hora, no cada noche.",no:"Finanzas pregunta por qué la cuenta subió a la mitad desde junio. Nadie sabe qué trabajos la hicieron crecer, ni de quién son."},
   {b:"Un portátil lee los archivos",part:"sec",goal:"laptop",ok:"El catálogo revisó el pedido del portátil antes de leer una fila, y vio solo lo que su dueño puede.",no:"Un portátil de la oficina leyó los archivos bajo las tablas: estar en la red bastó."},
   {b:"La carga de facturación se atrasa",part:"orc",goal:"order",ok:"El trabajo de medidores esperó a que llegara la carga de facturación, y luego corrió.",no:"El trabajo de medidores corrió a las dos, como siempre, antes de la carga de facturación: la mitad de las lecturas no cruzó con nada."}],
  along:"A lo largo del camino",across:"Lo cruzan todo",partWord:"parte",prodWord:"producto",nothing:"nada aún",
  msg:{view_products:"La imagen lista productos, con sus logos: una parte sin nada debajo no se ve.",view_parts:"Primero las partes, cada una con su producto debajo: se ven las partes sin nada."},
